import javax.crypto.spec.SecretKeySpec;

class Example {
    void example1() {
        SecretKeySpec keySpec = new SecretKeySpec(new byte[32], "AES");
    }
    void example2() {
        byte[] key = new byte[32];
        SecretKeySpec keySpec = new SecretKeySpec(key, "AES");
    }
    void example3() {
        byte[] key = new byte[32];
        key[0] = 1;
        SecretKeySpec keySpec = new SecretKeySpec(key, "AES");
    }
    void example4() {
        byte[] key;
        key = new byte[32];
        SecretKeySpec keySpec = new SecretKeySpec(key, "AES");
    }
    void example5() {
        byte[] key = new byte[32];
        SecretKeySpec keySpec = new SecretKeySpec(key, 0, key.length, "AES");
    }
    void example6(byte[] source) {
        byte[] key = new byte[32]; // Report: the later reassignment cannot change the key
        SecretKeySpec keySpec = new SecretKeySpec(key, "AES");
        key = source;
    }
}

import java.security.SecureRandom;
import javax.crypto.spec.SecretKeySpec;

class ExampleGood {
        void example1() {
            byte[] key = new byte[32];
            new SecureRandom().nextBytes(key);
            SecretKeySpec keySpec = new SecretKeySpec(key, "AES");
        }

        native int load(byte[] key);
        void example2() {
            byte[] key = new byte[32];
            load(key);
            SecretKeySpec keySpec = new SecretKeySpec(key, "AES");
        }

        void example3(byte[] source) {
            byte[] key = new byte[32];
            System.arraycopy(source, 0, key, 0, key.length);
            SecretKeySpec keySpec = new SecretKeySpec(key, "AES");
        }
}
